export class AudioEngine{
 constructor(enabled=true){this.enabled=enabled;}
 start(){if(!this.enabled)return;try{this.ctx??=new (window.AudioContext||window.webkitAudioContext)();this.ctx.resume();if(!this.wind){const c=this.ctx,buffer=c.createBuffer(1,c.sampleRate*3,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.12;const n=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();n.buffer=buffer;n.loop=true;filter.type='lowpass';filter.frequency.value=180;gain.gain.value=.06;n.connect(filter).connect(gain).connect(c.destination);n.start();this.wind=gain;}}catch{}}
 set(enabled){this.enabled=enabled;if(this.wind)this.wind.gain.value=enabled?.06:0;if(enabled)this.start();}
 play(type){if(!this.enabled)return;this.start();const c=this.ctx;if(!c)return;const map={arrow:[650,150,.07,'triangle'],magic:[240,850,.16,'sine'],blast:[90,30,.3,'sawtooth'],bubble:[65,140,.2,'sine'],horn:[130,196,.7,'sawtooth'],coin:[700,1050,.1,'sine'],build:[180,380,.12,'square'],hit:[110,50,.07,'triangle']};const [from,to,dur,wave]=map[type]||map.hit;const o=c.createOscillator(),g=c.createGain();o.type=wave;o.frequency.setValueAtTime(from,c.currentTime);o.frequency.exponentialRampToValueAtTime(to,c.currentTime+dur);g.gain.setValueAtTime(type==='horn'?.07:.035,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+dur);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+dur);}
}
